ReplacementContent:
"                        {checkPosAccess('Billing', 'order_note') && (
                        <div className={`flex-[1.5] min-w-0 h-8 rounded-full px-3 flex items-center transition-colors ${
                          isDark ? 'bg-[#0d1117] border border-gray-800' : 'bg-[#f1f3f4]'
                        }`}>
                          <input 
                            type="text" 
                            id="kot-note-input"
                            placeholder={activeTrayTab === 'PreOrder' ? "Pre-order instructions..." : "KOT Note"} 
                            value={activeTrayTab === 'PreOrder' ? preOrderNotes : kotNote}
                            onChange={e => activeTrayTab === 'PreOrder' ? setPreOrderNotes(e.target.value) : setKOTNote(e.target.value)}
                            onFocus={() => {
                              if (posSettings.showVirtualKeyboard) {
                                  if (activeTrayTab === 'PreOrder') {
                                    setKeyboardTarget({ value: preOrderNotes, setValue: setPreOrderNotes, type: 'text' });
                                  } else {
                                    setKeyboardTarget({ value: kotNote, setValue: setKOTNote, type: 'text' });
                                  }
                              }
                            }}
                            className={`w-full bg-transparent text-[10px] font-bold outline-none transition-colors ${
                              isDark ? 'text-gray-300 placeholder-gray-600' : 'text-slate-800 placeholder-slate-400'
                            }`} 
                          />
                        </div>
                        )}"

